import{_ as p,o as a,c as l,ai as e}from"./chunks/framework.BxxKhjs3.js";const i="/pub-blog/assets/image-20260323093757794.CTqyiP9C.png",t="/pub-blog/assets/image-20260323093828298.B4MPkWDw.png",s="/pub-blog/assets/image-20260323093853668.DvDu-qEj.png",o="/pub-blog/assets/image-20260323094004395.DPXvemeJ.png",r="/pub-blog/assets/image-20260323093935796.CezWdpsW.png",g="/pub-blog/assets/image-20260323094045127.2_Rl4hAz.png",c="/pub-blog/assets/image-20260323094111330.BYLV9Gio.png",h="/pub-blog/assets/image-20260322111544610.MuVKGFTo.png",m="/pub-blog/assets/image-20260323095955133.0RIf1Lpq.png",O=JSON.parse('{"title":"小龙虾 OpenClaw 治好了我的焦虑","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/小龙虾-openclaw-治好了我的焦虑/小龙虾-openclaw-治好了我的焦虑.md","filePath":"AI人工智能/小龙虾-openclaw-治好了我的焦虑/小龙虾-openclaw-治好了我的焦虑.md","lastUpdated":1774231228000,"__rawMarkdown":"# 小龙虾 OpenClaw 治好了我的焦虑\\n\\n> 不是因为它让我一夜暴富，而是它终于把“想很多”变成了“做出来”\\n\\n![](assets/image-20260323093757794.png)\\n\\n## 一、我焦虑的，不是没机会，而是机会太多\\n\\n前段时间，我整个人都处在一种很拧巴的状态里。\\n\\n朋友圈里，有人在晒 AI 副业收入，有人在讲大模型变现，有人在说“再不上车就晚了”。我每天刷公众号、知识星球、社群消息，越看越觉得机会很多，越看越觉得自己好像随时会错过什么。\\n\\n**但问题也恰恰在这里：风口太多了，我到底该抓哪个？**\\n\\n- 做 AI 绘画？感觉已经开始卷\\n- 搞大模型应用？门槛看起来不低\\n- 研究智能体？又不知道从哪一步开始\\n- 想做内容变现？脑子里有想法，手上却迟迟没动作\\n\\n后来我才意识到，自己不是没有方向，而是一直在“收集机会”，却没有真正进入执行。\\n\\n**知道得越多，行动得越少；看得越多，心里越慌。**\\n\\n直到我开始折腾 OpenClaw，社区里大家都叫它“小龙虾”。\\n\\n![](assets/image-20260323093828298.png)\\n\\n## 二、如果你看过我前面几篇文章，就会知道我不是突然开窍的\\n\\n很多人现在看我聊小龙虾，可能会觉得我是一下子就被它“治愈”了。\\n\\n其实不是。\\n\\n我和 OpenClaw 的关系，是一点点折腾出来的。\\n\\n一开始，我也是先去研究怎么把它装起来，怎么配模型的 key，怎么接飞书机器人，怎么让它真正跑起来。那时候我最大的感受还不是“这个东西真强”，而是：\\n\\n**它不像一个只会聊天的窗口，它更像一个真的能被我招进来上班的 AI 助手。**\\n\\n它可以 24 小时在线，可以接消息，可以继续执行任务，也可以在浏览器和电脑里替我做很多重复动作。\\n\\n当我第一次把这些基础环节跑通的时候，我心里一下子踏实了很多。因为我终于不是在围观别人的案例了，我自己手里也有了一个能动起来的东西。\\n\\n![](assets/image-20260323093853668.png)\\n\\n## 三、真正让我开始上头的，是我发现“只装起来还远远不够”\\n\\n后来我很快发现，只是把 OpenClaw 装好，其实还不算真正会用。\\n\\n你把它装起来，它只是一个底座。你开始给它装各种 Skill，它的能力才像是真的被一点点打开了。\\n\\n于是我又继续折腾 ClawHub，研究 Skill 的分类、安装方式、工作区能力，还开始慢慢理解：原来 OpenClaw 不是一个固定死的工具，而是一个可以不断扩展能力的系统。\\n\\n这一步对我心态的影响特别大。\\n\\n以前我总觉得，很多事情之所以让我焦虑，是因为所有流程都要我自己盯着，所有能力都要我自己现学。\\n\\n后来有了 Skill 这个概念之后，我开始意识到：\\n\\n- 有些任务是可以拆出去的\\n- 有些能力是可以后装的\\n- 有些流程不是我亲手点完每一步才算推进\\n\\n**焦虑的人最怕的，其实不是忙，而是什么都只能靠自己。**\\n\\n而小龙虾最先帮我缓解的，就是这种感觉。\\n\\n## 四、几次真实的折腾之后，我才真的被它说服了\\n\\n如果只是装起来、聊几句天，我不会写下这篇文章。真正让我改观的，是后面几次很具体的经历。\\n\\n### 1. 它第一次替我接过了重复劳动\\n\\n后来我拿 OpenClaw 去做小红书自动发帖。\\n\\n以前写完内容之后，我还得自己去登录、粘贴、检查、发布。单看每一步都不难，但非常碎，也很消耗注意力。\\n\\n装上对应的 Skill 之后，我只需要给一句明确指令，它就能自己去走流程。第一次登录配置完，后面很多动作都可以顺着做下去。\\n\\n那一刻我真正感受到的，不是“它帮我发了一篇帖子”，而是：\\n\\n**原来内容发布这种重复劳动，真的可以从我的待办里被拿掉一部分。**\\n\\n![](assets/image-20260323094004395.png)\\n\\n### 2. 它也逼着我从“迷信工具”，变成“理解工具”\\n\\n再后来，我碰到过搜索网络资讯老是限频的问题。\\n\\n一开始我也会怀疑，是不是小龙虾不好用了，是不是这个东西根本没别人说得那么神。\\n\\n但继续折腾之后我才发现，很多时候不是 OpenClaw 本身不行，而是模型套餐频率、默认搜索工具、外部 API 配置这些现实问题在卡住它。\\n\\n后来我开始换思路，给它装替代的搜索 Skill，重新配置默认能力，把问题一个个排掉。\\n\\n这一段经历反而让我更安心了。\\n\\n因为真正让人焦虑的，从来不是“出问题”，而是“出了问题我完全不知道该怎么办”。\\n\\n而当你开始知道问题在哪里、该怎么配、怎么替换方案，焦虑就会少很多。\\n\\n![](assets/image-20260323093935796.png)\\n\\n### 3. 它开始像一个能持续产出的搭子，而不只是聊天助手\\n\\n再往后，我又拿它做了几件更有意思的事。\\n\\n我让它帮我拆解网络爆文，分析标题套路、内容结构、情绪钩子。以前我写内容更多靠感觉，后来我可以先让它站在读者视角帮我拆，再决定自己怎么写。\\n\\n我还单独“招聘”了一个小说家 Agent，让它按照我给的规则去连续跑长任务，去尝试生成一部长篇小说。它告诉我可能要跑十几个小时，那一刻我突然特别有感触：\\n\\n**原来那些过去因为我没时间、没精力、没耐心而一直搁着的想法，现在真的可以有人替我一直往前推。**\\n\\n这时候我才真正理解，为什么大家会把 OpenClaw 叫作“小龙虾”。\\n\\n它不一定每次都完美，但它真的能一直干活。\\n\\n\\n\\n## 五、小龙虾没有消灭我的焦虑，但它改变了焦虑的方向\\n\\n用了这一段时间之后，我最大的变化不是“从此不焦虑了”，而是终于从空转里出来了。\\n\\n**以前我的焦虑是：**\\n\\n- 怕错过风口\\n- 怕别人已经靠 AI 跑得很远\\n- 怕自己懂得还不够多\\n- 怕每件事都要从头学、从头做\\n\\n**现在我的焦虑是：**\\n\\n- 这个流程还能不能再自动化一点\\n- 这个 Skill 能不能换一个更稳的\\n- 这个 Agent 能不能多接一点活\\n- 我能不能把时间留给更重要的判断和创作\\n\\n这两种焦虑看起来都叫焦虑，但完全不是一回事。\\n\\n前一种会让人不断刷信息，迟迟不动手。\\n\\n后一种虽然也会让人继续折腾，但它至少会把你推向结果。\\n\\n![](assets/image-20260323094045127.png)\\n\\n## 六、如果你现在也很慌，可以先养一只“小龙虾”\\n\\n如果你最近也被 AI 风口搞得有点乱，我的建议不是让你去追所有热点，而是先找一个真的能跑起来的工具，把它接入你的日常工作。\\n\\nOpenClaw 对我最大的价值，不是让我一夜暴富，而是让我慢慢建立起一种很踏实的感觉：\\n\\n**我不在线的时候，很多事情也可以继续往前走。**\\n\\n当你有了这种感觉，心会稳很多。\\n\\n它可能帮你做不到所有事，但至少能先帮你：\\n\\n- 接住一部分重复劳动\\n- 维持持续输出\\n- 把脑子里的想法更快落到执行\\n- 让你从“总想学更多”变成“先做成一个再说”\\n\\n这对我来说，已经足够治好很大一部分焦虑了。\\n\\n![](assets/image-20260323094111330.png)\\n\\n---\\n\\n## 加入微信龙虾群\\n\\n如果你也对 OpenClaw、对 AI 智能体感兴趣，欢迎加入我们的微信龙虾群。\\n\\n群里都是志同道合的朋友，大家一起：\\n\\n- 分享使用经验\\n- 交流部署技巧\\n- 探讨变现思路\\n- 互相打气加油\\n\\n万少建立了一个专门讨论小龙虾**OpenClaw**的微信群（已经满200人），大家可以互相交流和分享关于小龙虾生态的资讯消息。\\n\\n![](assets/image-20260322111544610.MuVKGFTo.png)\\n\\n\\n\\n![](assets/image-20260323095955133.png)\\n\\n\\n\\n---\\n\\n> **最后想说：**\\n>\\n> 风口永远都有，错过一个还有下一个。\\n>\\n> 但真正重要的，不是追上所有热点，而是先找到一套能让自己持续行动、持续产出的方式。\\n>\\n> 小龙虾 OpenClaw，没有替我做决定，但它帮我把很多原本停在脑子里的想法，真正推进了下去。\\n>\\n> 这就是它最打动我的地方。\\n\\n---\\n\\n*如果你觉得这篇文章对你有帮助，欢迎点赞、在看、转发，让更多人受益。*"}'),_={name:"AI人工智能/小龙虾-openclaw-治好了我的焦虑/小龙虾-openclaw-治好了我的焦虑.md"};function u(d,n,b,w,k,C){return a(),l("div",null,[...n[0]||(n[0]=[e('<h1 id="小龙虾-openclaw-治好了我的焦虑" tabindex="-1">小龙虾 OpenClaw 治好了我的焦虑 <a class="header-anchor" href="#小龙虾-openclaw-治好了我的焦虑" aria-label="Permalink to &quot;小龙虾 OpenClaw 治好了我的焦虑&quot;">​</a></h1><blockquote><p>不是因为它让我一夜暴富，而是它终于把“想很多”变成了“做出来”</p></blockquote><p><img src="'+i+'" alt=""></p><h2 id="一、我焦虑的-不是没机会-而是机会太多" tabindex="-1">一、我焦虑的，不是没机会，而是机会太多 <a class="header-anchor" href="#一、我焦虑的-不是没机会-而是机会太多" aria-label="Permalink to &quot;一、我焦虑的，不是没机会，而是机会太多&quot;">​</a></h2><p>前段时间，我整个人都处在一种很拧巴的状态里。</p><p>朋友圈里，有人在晒 AI 副业收入，有人在讲大模型变现，有人在说“再不上车就晚了”。我每天刷公众号、知识星球、社群消息，越看越觉得机会很多，越看越觉得自己好像随时会错过什么。</p><p><strong>但问题也恰恰在这里：风口太多了，我到底该抓哪个？</strong></p><ul><li>做 AI 绘画？感觉已经开始卷</li><li>搞大模型应用？门槛看起来不低</li><li>研究智能体？又不知道从哪一步开始</li><li>想做内容变现？脑子里有想法，手上却迟迟没动作</li></ul><p>后来我才意识到，自己不是没有方向，而是一直在“收集机会”，却没有真正进入执行。</p><p><strong>知道得越多，行动得越少；看得越多，心里越慌。</strong></p><p>直到我开始折腾 OpenClaw，社区里大家都叫它“小龙虾”。</p><p><img src="'+t+'" alt=""></p><h2 id="二、如果你看过我前面几篇文章-就会知道我不是突然开窍的" tabindex="-1">二、如果你看过我前面几篇文章，就会知道我不是突然开窍的 <a class="header-anchor" href="#二、如果你看过我前面几篇文章-就会知道我不是突然开窍的" aria-label="Permalink to &quot;二、如果你看过我前面几篇文章，就会知道我不是突然开窍的&quot;">​</a></h2><p>很多人现在看我聊小龙虾，可能会觉得我是一下子就被它“治愈”了。</p><p>其实不是。</p><p>我和 OpenClaw 的关系，是一点点折腾出来的。</p><p>一开始，我也是先去研究怎么把它装起来，怎么配模型的 key，怎么接飞书机器人，怎么让它真正跑起来。那时候我最大的感受还不是“这个东西真强”，而是：</p><p><strong>它不像一个只会聊天的窗口，它更像一个真的能被我招进来上班的 AI 助手。</strong></p><p>它可以 24 小时在线，可以接消息，可以继续执行任务，也可以在浏览器和电脑里替我做很多重复动作。</p><p>当我第一次把这些基础环节跑通的时候，我心里一下子踏实了很多。因为我终于不是在围观别人的案例了，我自己手里也有了一个能动起来的东西。</p><p><img src="'+s+'" alt=""></p><h2 id="三、真正让我开始上头的-是我发现-只装起来还远远不够" tabindex="-1">三、真正让我开始上头的，是我发现“只装起来还远远不够” <a class="header-anchor" href="#三、真正让我开始上头的-是我发现-只装起来还远远不够" aria-label="Permalink to &quot;三、真正让我开始上头的，是我发现“只装起来还远远不够”&quot;">​</a></h2><p>后来我很快发现，只是把 OpenClaw 装好，其实还不算真正会用。</p><p>你把它装起来，它只是一个底座。你开始给它装各种 Skill，它的能力才像是真的被一点点打开了。</p><p>于是我又继续折腾 ClawHub，研究 Skill 的分类、安装方式、工作区能力，还开始慢慢理解：原来 OpenClaw 不是一个固定死的工具，而是一个可以不断扩展能力的系统。</p><p>这一步对我心态的影响特别大。</p><p>以前我总觉得，很多事情之所以让我焦虑，是因为所有流程都要我自己盯着，所有能力都要我自己现学。</p><p>后来有了 Skill 这个概念之后，我开始意识到：</p><ul><li>有些任务是可以拆出去的</li><li>有些能力是可以后装的</li><li>有些流程不是我亲手点完每一步才算推进</li></ul><p><strong>焦虑的人最怕的，其实不是忙，而是什么都只能靠自己。</strong></p><p>而小龙虾最先帮我缓解的，就是这种感觉。</p><h2 id="四、几次真实的折腾之后-我才真的被它说服了" tabindex="-1">四、几次真实的折腾之后，我才真的被它说服了 <a class="header-anchor" href="#四、几次真实的折腾之后-我才真的被它说服了" aria-label="Permalink to &quot;四、几次真实的折腾之后，我才真的被它说服了&quot;">​</a></h2><p>如果只是装起来、聊几句天，我不会写下这篇文章。真正让我改观的，是后面几次很具体的经历。</p><h3 id="_1-它第一次替我接过了重复劳动" tabindex="-1">1. 它第一次替我接过了重复劳动 <a class="header-anchor" href="#_1-它第一次替我接过了重复劳动" aria-label="Permalink to &quot;1. 它第一次替我接过了重复劳动&quot;">​</a></h3><p>后来我拿 OpenClaw 去做小红书自动发帖。</p><p>以前写完内容之后，我还得自己去登录、粘贴、检查、发布。单看每一步都不难，但非常碎，也很消耗注意力。</p><p>装上对应的 Skill 之后，我只需要给一句明确指令，它就能自己去走流程。第一次登录配置完，后面很多动作都可以顺着做下去。</p><p>那一刻我真正感受到的，不是“它帮我发了一篇帖子”，而是：</p><p><strong>原来内容发布这种重复劳动，真的可以从我的待办里被拿掉一部分。</strong></p><p><img src="'+o+'" alt=""></p><h3 id="_2-它也逼着我从-迷信工具-变成-理解工具" tabindex="-1">2. 它也逼着我从“迷信工具”，变成“理解工具” <a class="header-anchor" href="#_2-它也逼着我从-迷信工具-变成-理解工具" aria-label="Permalink to &quot;2. 它也逼着我从“迷信工具”，变成“理解工具”&quot;">​</a></h3><p>再后来，我碰到过搜索网络资讯老是限频的问题。</p><p>一开始我也会怀疑，是不是小龙虾不好用了，是不是这个东西根本没别人说得那么神。</p><p>但继续折腾之后我才发现，很多时候不是 OpenClaw 本身不行，而是模型套餐频率、默认搜索工具、外部 API 配置这些现实问题在卡住它。</p><p>后来我开始换思路，给它装替代的搜索 Skill，重新配置默认能力，把问题一个个排掉。</p><p>这一段经历反而让我更安心了。</p><p>因为真正让人焦虑的，从来不是“出问题”，而是“出了问题我完全不知道该怎么办”。</p><p>而当你开始知道问题在哪里、该怎么配、怎么替换方案，焦虑就会少很多。</p><p><img src="'+r+'" alt=""></p><h3 id="_3-它开始像一个能持续产出的搭子-而不只是聊天助手" tabindex="-1">3. 它开始像一个能持续产出的搭子，而不只是聊天助手 <a class="header-anchor" href="#_3-它开始像一个能持续产出的搭子-而不只是聊天助手" aria-label="Permalink to &quot;3. 它开始像一个能持续产出的搭子，而不只是聊天助手&quot;">​</a></h3><p>再往后，我又拿它做了几件更有意思的事。</p><p>我让它帮我拆解网络爆文，分析标题套路、内容结构、情绪钩子。以前我写内容更多靠感觉，后来我可以先让它站在读者视角帮我拆，再决定自己怎么写。</p><p>我还单独“招聘”了一个小说家 Agent，让它按照我给的规则去连续跑长任务，去尝试生成一部长篇小说。它告诉我可能要跑十几个小时，那一刻我突然特别有感触：</p><p><strong>原来那些过去因为我没时间、没精力、没耐心而一直搁着的想法，现在真的可以有人替我一直往前推。</strong></p><p>这时候我才真正理解，为什么大家会把 OpenClaw 叫作“小龙虾”。</p><p>它不一定每次都完美，但它真的能一直干活。</p><h2 id="五、小龙虾没有消灭我的焦虑-但它改变了焦虑的方向" tabindex="-1">五、小龙虾没有消灭我的焦虑，但它改变了焦虑的方向 <a class="header-anchor" href="#五、小龙虾没有消灭我的焦虑-但它改变了焦虑的方向" aria-label="Permalink to &quot;五、小龙虾没有消灭我的焦虑，但它改变了焦虑的方向&quot;">​</a></h2><p>用了这一段时间之后，我最大的变化不是“从此不焦虑了”，而是终于从空转里出来了。</p><p><strong>以前我的焦虑是：</strong></p><ul><li>怕错过风口</li><li>怕别人已经靠 AI 跑得很远</li><li>怕自己懂得还不够多</li><li>怕每件事都要从头学、从头做</li></ul><p><strong>现在我的焦虑是：</strong></p><ul><li>这个流程还能不能再自动化一点</li><li>这个 Skill 能不能换一个更稳的</li><li>这个 Agent 能不能多接一点活</li><li>我能不能把时间留给更重要的判断和创作</li></ul><p>这两种焦虑看起来都叫焦虑，但完全不是一回事。</p><p>前一种会让人不断刷信息，迟迟不动手。</p><p>后一种虽然也会让人继续折腾，但它至少会把你推向结果。</p><p><img src="'+g+'" alt=""></p><h2 id="六、如果你现在也很慌-可以先养一只-小龙虾" tabindex="-1">六、如果你现在也很慌，可以先养一只“小龙虾” <a class="header-anchor" href="#六、如果你现在也很慌-可以先养一只-小龙虾" aria-label="Permalink to &quot;六、如果你现在也很慌，可以先养一只“小龙虾”&quot;">​</a></h2><p>如果你最近也被 AI 风口搞得有点乱，我的建议不是让你去追所有热点，而是先找一个真的能跑起来的工具，把它接入你的日常工作。</p><p>OpenClaw 对我最大的价值，不是让我一夜暴富，而是让我慢慢建立起一种很踏实的感觉：</p><p><strong>我不在线的时候，很多事情也可以继续往前走。</strong></p><p>当你有了这种感觉，心会稳很多。</p><p>它可能帮你做不到所有事，但至少能先帮你：</p><ul><li>接住一部分重复劳动</li><li>维持持续输出</li><li>把脑子里的想法更快落到执行</li><li>让你从“总想学更多”变成“先做成一个再说”</li></ul><p>这对我来说，已经足够治好很大一部分焦虑了。</p><p><img src="'+c+'" alt=""></p><hr><h2 id="加入微信龙虾群" tabindex="-1">加入微信龙虾群 <a class="header-anchor" href="#加入微信龙虾群" aria-label="Permalink to &quot;加入微信龙虾群&quot;">​</a></h2><p>如果你也对 OpenClaw、对 AI 智能体感兴趣，欢迎加入我们的微信龙虾群。</p><p>群里都是志同道合的朋友，大家一起：</p><ul><li>分享使用经验</li><li>交流部署技巧</li><li>探讨变现思路</li><li>互相打气加油</li></ul><p>万少建立了一个专门讨论小龙虾<strong>OpenClaw</strong>的微信群（已经满200人），大家可以互相交流和分享关于小龙虾生态的资讯消息。</p><p><img src="'+h+'" alt=""></p><p><img src="'+m+'" alt=""></p><hr><blockquote><p><strong>最后想说：</strong></p><p>风口永远都有，错过一个还有下一个。</p><p>但真正重要的，不是追上所有热点，而是先找到一套能让自己持续行动、持续产出的方式。</p><p>小龙虾 OpenClaw，没有替我做决定，但它帮我把很多原本停在脑子里的想法，真正推进了下去。</p><p>这就是它最打动我的地方。</p></blockquote><hr><p><em>如果你觉得这篇文章对你有帮助，欢迎点赞、在看、转发，让更多人受益。</em></p>',87)])])}const A=p(_,[["render",u]]);export{O as __pageData,A as default};
